// Circular satellite orbits and the nominal GPS constellation (same model as main.py).
// Physics frame: Earth-centred, non-rotating, z = north pole. Units: metres, seconds, radians.
// A satellite is a plain object: { name, plane, a, inc, raan, u0 }
//   a = orbit radius, inc = inclination, raan = plane orientation, u0 = phase at t = 0.

export const GM = 3.986004418e14;      // m^3/s^2
export const R_E = 6371e3;             // m
export const A = 26560e3;              // GPS orbit radius (m)
export const INC = (55 * Math.PI) / 180;
export const N_PLANES = 6;
export const PER_PLANE = 4;
export const N_SAT = N_PLANES * PER_PLANE;

export const periodOf = (sat) => 2 * Math.PI * Math.sqrt(sat.a ** 3 / GM); // GPS: ~11.97 h

// Position [x, y, z] of a satellite at time t seconds.
export function satPosition(sat, t) {
  const u = (2 * Math.PI * t) / periodOf(sat) + sat.u0;                // argument of latitude
  const x = sat.a * Math.cos(u), y = sat.a * Math.sin(u);              // in-plane coordinates
  const px = x, py = y * Math.cos(sat.inc), pz = y * Math.sin(sat.inc); // tilt by inclination
  const cr = Math.cos(sat.raan), sr = Math.sin(sat.raan);              // rotate about z by RAAN
  return [cr * px - sr * py, sr * px + cr * py, pz];
}

// The nominal 24-satellite constellation: 6 planes x 4 satellites, phases staggered between planes.
export function nominalConstellation() {
  const sats = [];
  for (let i = 0; i < N_SAT; i++) {
    const plane = Math.floor(i / PER_PLANE), slot = i % PER_PLANE;
    sats.push({
      name: `GPS-${"ABCDEF"[plane]}${slot + 1}`,
      plane,
      a: A,
      inc: INC,
      raan: (2 * Math.PI * plane) / N_PLANES,
      u0: (2 * Math.PI * slot) / PER_PLANE + (plane * 2 * Math.PI) / N_SAT,
    });
  }
  return sats;
}
EOF
cat > dop.js <<'EOF'
// Dilution of precision (DOP) and the Monte Carlo coverage simulation.
import { R_E, satPosition } from "./orbit.js";

// Invert a 4x4 matrix (array of 4 rows) by Gauss-Jordan elimination. Returns null if singular.
function invert4(M) {
  const a = M.map((row, i) => [...row, ...[0, 1, 2, 3].map((j) => (i === j ? 1 : 0))]);
  for (let c = 0; c < 4; c++) {
    let p = c;
    for (let r = c + 1; r < 4; r++) if (Math.abs(a[r][c]) > Math.abs(a[p][c])) p = r;
    if (Math.abs(a[p][c]) < 1e-9) return null;
    [a[c], a[p]] = [a[p], a[c]];
    const d = a[c][c];
    for (let k = 0; k < 8; k++) a[c][k] /= d;
    for (let r = 0; r < 4; r++) {
      if (r === c) continue;
      const f = a[r][c];
      for (let k = 0; k < 8; k++) a[r][k] -= f * a[c][k];
    }
  }
  return a.map((row) => row.slice(4));
}

// DOP from unit line-of-sight vectors receiver -> satellite (one [ux, uy, uz] per visible satellite).
// Each row of G is [-u, 1] (unknowns x, y, z, clock bias). Q = (G^T G)^-1.
// PDOP = sqrt(Qxx + Qyy + Qzz), GDOP = sqrt(trace Q). Returns null with < 4 satellites or a singular G^T G.
export function dopFromUnits(units) {
  if (units.length < 4) return null;
  const GtG = [0, 1, 2, 3].map(() => [0, 0, 0, 0]);
  for (const [ux, uy, uz] of units) {
    const g = [-ux, -uy, -uz, 1];
    for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) GtG[i][j] += g[i] * g[j];
  }
  const Q = invert4(GtG);
  if (!Q) return null;
  const pdop = Math.sqrt(Q[0][0] + Q[1][1] + Q[2][2]);
  return { pdop, gdop: Math.sqrt(pdop ** 2 + Q[3][3]) };
}

const median = (xs) => {
  if (!xs.length) return NaN;
  const s = [...xs].sort((a, b) => a - b);
  return s[Math.floor(s.length / 2)];
};

// Monte Carlo: n random surface points (uniform on the sphere) at random times in [0, tMax].
// Counts satellites above the elevation mask and computes DOP from those.
// hist[k] = fraction of samples with exactly k visible satellites.
export function monteCarlo(sats, { n = 5000, maskDeg = 5, rng = Math.random, tMax = 86400, pdopLimit = 6 } = {}) {
  const sinMask = Math.sin((maskDeg * Math.PI) / 180);
  const hist = [];
  const pdops = [], gdops = [];
  let sumVis = 0, minVis = Infinity, maxVis = 0, ge4 = 0, good = 0;
  for (let i = 0; i < n; i++) {
    const z = 2 * rng() - 1, phi = 2 * Math.PI * rng(), r = Math.sqrt(1 - z * z);
    const up = [r * Math.cos(phi), r * Math.sin(phi), z];              // local vertical = unit position
    const t = rng() * tMax;
    const units = [];
    for (const sat of sats) {
      const p = satPosition(sat, t);
      const d = [p[0] - R_E * up[0], p[1] - R_E * up[1], p[2] - R_E * up[2]];
      const len = Math.hypot(d[0], d[1], d[2]);
      const u = [d[0] / len, d[1] / len, d[2] / len];
      if (u[0] * up[0] + u[1] * up[1] + u[2] * up[2] > sinMask) units.push(u); // sin(elevation) > sin(mask)
    }
    const nv = units.length;
    hist[nv] = (hist[nv] || 0) + 1;
    sumVis += nv; minVis = Math.min(minVis, nv); maxVis = Math.max(maxVis, nv);
    if (nv >= 4) ge4++;
    const dop = dopFromUnits(units);
    if (dop) {
      pdops.push(dop.pdop); gdops.push(dop.gdop);
      if (dop.pdop <= pdopLimit) good++;
    }
  }
  for (let k = 0; k <= maxVis; k++) hist[k] = (hist[k] || 0) / n;
  return {
    n, maskDeg, nSats: sats.length, pdopLimit, hist,
    meanVis: sumVis / n, minVis: n ? minVis : 0, maxVis,
    pGe4: ge4 / n, pGood: good / n,
    medPdop: median(pdops), medGdop: median(gdops),
  };
}
EOF
cat > tests.js <<'EOF'
// Checks for orbit.js and dop.js. Open test.html in a browser (or see README of the run command).
import { R_E, A, INC, N_SAT, nominalConstellation, satPosition } from "./orbit.js";
import { dopFromUnits, monteCarlo } from "./dop.js";

const results = [];
const check = (name, ok, detail) => results.push(`${ok ? "PASS" : "FAIL"}  ${name}  ${detail}`);

// Small seeded random generator (mulberry32) so the Monte Carlo checks are repeatable.
function seeded(seed) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const sats = nominalConstellation();

// 1. Constellation: 24 satellites, all at radius A, none beyond |z| = A sin(inc).
let maxR = 0, maxZ = 0;
for (const s of sats) for (let t = 0; t < 43200; t += 600) {
  const p = satPosition(s, t);
  maxR = Math.max(maxR, Math.abs(Math.hypot(...p) - A)); maxZ = Math.max(maxZ, Math.abs(p[2]));
}
check("24 satellites", sats.length === N_SAT, `got ${sats.length}`);
check("circular orbit radius", maxR < 1e-3, `max |r - A| = ${maxR.toExponential(2)} m`);
check("max |z| = A sin(55 deg)", Math.abs(maxZ / A - Math.sin(INC)) < 1e-3, `${(maxZ / A).toFixed(4)} vs ${Math.sin(INC).toFixed(4)}`);

// 2. JS positions vs numpy positions from main.py at t = 12345 s (satellites 0, 5, 17).
const ref = { 0: [-6050073.3647, 14833691.5031, 21184706.9527], 5: [-5479587.2036, -23873279.2226, -10270066.3705], 17: [-8782221.0721, 13951633.7671, -20824459.3757] };
for (const [i, r] of Object.entries(ref)) {
  const p = satPosition(sats[i], 12345);
  const err = Math.hypot(p[0] - r[0], p[1] - r[1], p[2] - r[2]);
  check(`satellite ${i} matches main.py`, err < 1, `error ${err.toExponential(2)} m`);
}

// 3. DOP by hand: one satellite at zenith + three on the horizon 120 deg apart in azimuth.
//    G^T G is block diagonal, so PDOP = sqrt(8/3), GDOP = sqrt(3).
const s3 = Math.sqrt(3) / 2;
const d = dopFromUnits([[0, 0, 1], [1, 0, 0], [-0.5, s3, 0], [-0.5, -s3, 0]]);
check("hand DOP: PDOP", Math.abs(d.pdop - Math.sqrt(8 / 3)) < 1e-9, `${d.pdop.toFixed(4)} vs ${Math.sqrt(8 / 3).toFixed(4)}`);
check("hand DOP: GDOP", Math.abs(d.gdop - Math.sqrt(3)) < 1e-9, `${d.gdop.toFixed(4)} vs ${Math.sqrt(3).toFixed(4)}`);
check("fewer than 4 satellites gives no DOP", dopFromUnits([[0, 0, 1], [1, 0, 0], [0, 1, 0]]) === null, "");

// 4. One satellite: Monte Carlo coverage vs analytic spherical-cap fraction.
//    Earth central angle seen at elevation mask e is lam = arccos(R cos e / a) - e; the cap covers (1 - cos lam) / 2.
const e = (5 * Math.PI) / 180;
const exact = (1 - Math.cos(Math.acos((R_E * Math.cos(e)) / A) - e)) / 2;
const n = 20000;
const one = monteCarlo([sats[0]], { n, maskDeg: 5, rng: seeded(1) });
