    const p = satPosition(e.sat, t);
    const d = [p[0] - recvPhys[0], p[1] - recvPhys[1], p[2] - recvPhys[2]], len = Math.hypot(...d);
    const u = [d[0] / len, d[1] / len, d[2] / len];
