    (dop ? ` · PDOP ${dop.pdop.toFixed(2)}` : " · no position fix (need 4)");
  if ($("recv").textContent !== text) $("recv").textContent = text;
  if (hovered) updateTooltip();
  controls.update();
  renderer.render(scene, camera);
});

